// FUNCTION: BFME2 0x004A1950 size=45 name=?rva004A1950@Rva004A1950@@UAEXXZ evidence=?:placeholder tier=B hypothesis:cohesion
void SlavedUpdate::onObjectCreated()
{
	const SlavedUpdateModuleData *data = static_cast<const SlavedUpdateModuleData *>(getModuleData());
	if (data->m_repairRatePerSecond > 0.0f)
		getObject()->setModelConditionState((ModelConditionFlagType)MC_PACKING);
}

// FUNCTION: BFME2 0x004A197D size=236 name=?setRepairModelConditionStates@SlavedUpdate@@QAEXW4ModelConditionFlagType@@@Z evidence=N:ledger tier=B hypothesis:cohesion
void SlavedUpdate::setRepairModelConditionStates(ModelConditionFlagType flag)
{
	Object *obj = getObject();
	obj->clearModelConditionState((UnsignedInt)MC_PACKING);
	obj->clearModelConditionState((UnsignedInt)MC_UNPACKING);
	obj->clearModelConditionState((UnsignedInt)MC_FIRING_B);
	obj->clearModelConditionState((UnsignedInt)MC_FIRING_C);
	obj->clearModelConditionState((UnsignedInt)MC_BETWEEN_FIRING_SHOTS_B);
	obj->clearModelConditionState((UnsignedInt)MC_BETWEEN_FIRING_SHOTS_C);
	obj->clearModelConditionState((UnsignedInt)MC_RELOADING_B);
	obj->clearModelConditionState((UnsignedInt)MC_RELOADING_C);
	obj->setModelConditionState(flag);
}

// FUNCTION: BFME2 0x004A1A69 size=174 name=?startSlavedEffects@SlavedUpdate@@QAEXPBVObject@@@Z evidence=N:ledger tier=A
void SlavedUpdate::startSlavedEffects(const Object *slaver)
{
	if (!slaver)
		return;
	m_slaverID = slaver->getID();
	const SlavedUpdateModuleData *data = static_cast<const SlavedUpdateModuleData *>(getModuleData());
	Real randomDirection = GetGameLogicRandomValueReal(0.0f, TWO_PI, const_cast<char *>(SLAVED_UPDATE_FILE), 862);
	m_goalPos.zero();
	m_goalPos.x += data->m_guardMaxRange * Cos(randomDirection);
	m_goalPos.y += data->m_guardMaxRange * Sin(randomDirection);
	if (data->m_markUnselectable)
		getObject()->setStatus((ObjectStatusTypes)3, true);
	Drawable *drawable = getObject()->getDrawable();
	if (drawable)
		drawable->inheritSlaverFlags(slaver, this);
}

// FUNCTION: BFME2 0x004A1B17 size=61 name=?stopSlavedEffects@SlavedUpdate@@QAEXXZ evidence=N:ledger tier=A
void SlavedUpdate::stopSlavedEffects()
{
	const SlavedUpdateModuleData *data = static_cast<const SlavedUpdateModuleData *>(getModuleData());
	if (data != NULL && data->m_dieOnMastersDeath)
		return;
	m_slaverID = INVALID_ID;
	m_goalPos.zero();
	getObject()->setStatus(OBJECT_STATUS_UNSELECTABLE, false);
	getObject()->clearDisabled(DISABLED_HELD);
}

// FUNCTION: BFME2 0x004A1B54 size=169 name=?xfer@Rva004A1855@@MAEXPAVXfer@@@Z evidence=?:placeholder tier=A
// The module base, then (not for a light CRC) the versioned record: the master's id, the goal position,
// the wait frames, the repair state's raw word, the flag at +0x3C, the id at +0x40 from version 2 and the
// two flags at +0x44 and +0x45 from version 3.
void SlavedUpdate::xfer(Xfer *xfer)
{
	UpdateModule::xfer(xfer);
	if (xfer->IsLightCRC())
		return;
	Xfer::Version version(1, 3);
	*xfer == version;
	XferObjectID(xfer, &m_slaverID);
	*xfer == m_goalPos;
	*xfer == m_waitFrames;
	xfer->XferRawBytes(&m_repairState, 4);
	*xfer == m_unk0x3C;
	if (version.m_minimum >= 2)
		XferObjectID(xfer, &m_unk0x40);
	if (version.m_minimum >= 3)
	{
		*xfer == m_unk0x44;
		*xfer == m_unk0x45;
	}
}

