// FUNCTION: BFME2 0x004A1C10 size=73 name=?endRepair@SlavedUpdate@@QAEXXZ evidence=N:ledger tier=A
void SlavedUpdate::endRepair()
{
	if (m_repairState != 0)
	{
		m_repairState = 0;
		m_waitFrames = s_waitFrames;
		m_unk0x3C = false;
		setRepairModelConditionStates((ModelConditionFlagType)MC_PACKING);
	}

	AIUpdateInterface *ai = getObject()->getAIUpdateInterface();
	if (ai != NULL)
	{
		ai->chooseLocomotorSet(0);
		Locomotor *locomotor = ai->m_curLocomotor;
		if (locomotor != NULL)
			locomotor->m_flags &= ~0x48u;
	}
}

// FUNCTION: BFME2 0x004A1C59 size=30 name=?onSlaverDamage@SlavedUpdate@@UAEXPBVRva00263895Member@@@Z evidence=N:ledger tier=A
void SlavedUpdate::onSlaverDamage(const DamageInfo *info)
{
	AIUpdateInterface *ai = getObject()->getAIUpdateInterface();
	if (ai != NULL)
		ai->getAICommandInterface()->aiGoProne(reinterpret_cast<const Rva003427DD *>(info), CMD_FROM_AI);
}

