// FUNCTION: BFME2 0x004A2144 size=276 name=?moveToNewRepairSpot@SlavedUpdate@@QAEXXZ evidence=N:ledger tier=A
// Picks a new spot within the repair range of the master (at a random altitude) and flies there.
void SlavedUpdate::moveToNewRepairSpot()
{
	const SlavedUpdateModuleData *data = static_cast<const SlavedUpdateModuleData *>(getModuleData());
	Object *me = getObject();
	Object *master = TheGameLogic->findObjectByID(m_slaverID);
	if (data->m_repairRange)
	{
		Real randomDirection = GetGameLogicRandomValueReal(0.0f, TWO_PI, const_cast<char *>(SLAVED_UPDATE_FILE), 828);
		m_goalPos.set(master->getPosition());
		m_goalPos.x += data->m_repairRange * Cos(randomDirection);
		m_goalPos.y += data->m_repairRange * Sin(randomDirection);
		m_goalPos.z = TheTerrainLogic->getGroundHeight(m_goalPos.x, m_goalPos.y);
		Real altitude = GetGameLogicRandomValueReal(data->m_repairMinAltitude, data->m_repairMaxAltitude, const_cast<char *>(SLAVED_UPDATE_FILE), 833);
		m_goalPos.z += altitude;
		AIUpdateInterface *ai = me->getAIUpdateInterface();
		if (ai)
		{
			ai->chooseLocomotorSet(4);
			ai->m_curLocomotor->m_flags |= 0x40;
			ai->getAICommandInterface()->aiMoveToPosition(&m_goalPos, CMD_FROM_AI);
			Locomotor *locomotor = ai->m_curLocomotor;
			if (locomotor)
				locomotor->m_flags |= 0x8;
		}
	}
}



